package io.knowledgebrain.collaboration;
import io.knowledgebrain.contracts.collaboration.assignmentrubric.v1.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP",matches=".+")
class AssignmentRubricKafkaIntegrationTest {
 @Test void immutableAttemptsMatchCdcBytesAndReplayWithoutAcknowledgement()throws Exception{
  var test=new AssignmentRubricStoreIntegrationTest();test.setup();var f=test.f;var v=test.change(0,1,test.initial()).rubric();test.change(1,1,test.items(v,"Revised criteria"));test.change(2,1,List.of());var expected=new HashMap<String,byte[]>();for(var bytes:f.f.jdbc.queryForList("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.rubricId())){var e=AssignmentRubricEnvelopeV1.parseFrom(bytes);expected.put(e.getEventId(),bytes);}assertEquals(3,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP"));options.put("group.id","group-validation-"+UUID.randomUUID());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.keystore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/group-kafka-test/ca.crt")));options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/group-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/group-kafka-test/user.key")));
  for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("collaboration.assignment-rubric.v1"));long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<3&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=AssignmentRubricEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),record.value());assertEquals(v.rubricId().toString(),record.key());assertEquals(f.f.trace,e.getTraceId());assertEquals(f.space.toString(),e.getSpaceId());assertEquals(f.f.owner.toString(),e.getActorId());var p=AssignmentRubricSnapshotV1.parseFrom(e.getPayload());assertEquals(test.assignment.toString(),p.getAssignmentId());assertEquals(f.group.toString(),p.getGroupId());assertEquals(1,p.getAssignmentVersion());assertTrue(p.getCriteriaCount()==0||p.getCriteriaList().stream().mapToInt(n->n.getMaxPoints()).sum()==100);for(var entry:Map.of("trace_id",f.f.trace,"schema_group","collaboration","schema_artifact","assignment-rubric-events","schema_version","1").entrySet())assertEquals(entry.getValue(),new String(record.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));seen.add(e.getEventId());}}assertEquals(expected.keySet(),seen);}
  System.out.println("PASS collaboration.assignment-rubric.v1 three byte-exact Group-shared rubric snapshots, stable IDs, trace/schema headers and unacknowledged replay");
 }
}
